export type LpcSpriteKey = (typeof LPC_SPRITE_KEYS)[number];

export type LpcSpriteRef = LpcSpriteKey | LpcSheetDefinitionFile;

export interface LpcMergeLayer {
  sprite: LpcSpriteRef;
  variant?: string;
  recolor?: string;
  zPos?: number;
  opacity?: number;
}

export function defineLpcMergeLayers<const T extends readonly LpcMergeLayer[]>(layers: T): T {
  return layers;
}
